import{_ as e,o,c as s,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Classificação e Simbiose de Raças Estrangeiras","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0052-异族分类与共生.md","filePath":"pt/0052-异族分类与共生.md"}'),t={name:"pt/0052-异族分类与共生.md"};function r(d,a,n,c,l,m){return o(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="classificacao-e-simbiose-de-racas-estrangeiras" tabindex="-1">Classificação e Simbiose de Raças Estrangeiras <a class="header-anchor" href="#classificacao-e-simbiose-de-racas-estrangeiras" aria-label="Permalink to &quot;Classificação e Simbiose de Raças Estrangeiras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>52</td></tr><tr><td>Módulo</td><td>Raças e Formas de Vida</td></tr><tr><td>Palavras-chave</td><td>Raças estrangeiras, critérios de classificação, modos de simbiose, respeito cultural, adaptação racial</td></tr></tbody></table><h2 id="i-definicao-do-conceito-de-racas-estrangeiras" tabindex="-1">I. Definição do Conceito de Raças Estrangeiras <a class="header-anchor" href="#i-definicao-do-conceito-de-racas-estrangeiras" aria-label="Permalink to &quot;I. Definição do Conceito de Raças Estrangeiras&quot;">​</a></h2><p>No contexto da Civilização Simbiótica da Âncora, &quot;raças estrangeiras&quot; é um conceito relativo à Raça Humana, referindo-se a todas as raças além da Raça Humana. É especialmente importante enfatizar que o conceito de &quot;raças estrangeiras&quot; tem apenas significado taxonômico e não carrega qualquer julgamento de valor ou significado discriminatório. No quadro da Constituição Simbiótica, as raças estrangeiras e a Raça Humana desfrutam de status jurídico e direitos básicos completamente iguais.</p><p>O objetivo da introdução do conceito de raças estrangeiras é compreender e estudar sistematicamente as várias formas de vida além da Raça Humana, fornecendo uma base científica para a formulação de políticas simbióticas direcionadas, medidas de proteção cultural e planos de adaptação racial, em vez de tratar as raças estrangeiras como &quot;o outro&quot; ou &quot;os estranhos&quot;.</p><h2 id="ii-criterios-de-classificacao-das-racas-estrangeiras" tabindex="-1">II. Critérios de Classificação das Raças Estrangeiras <a class="header-anchor" href="#ii-criterios-de-classificacao-das-racas-estrangeiras" aria-label="Permalink to &quot;II. Critérios de Classificação das Raças Estrangeiras&quot;">​</a></h2><p>As raças estrangeiras de Hengyuanzhou são classificadas de acordo com múltiplas dimensões, formando um sistema de classificação multidimensional:</p><h3 id="a-por-linhagem-de-vida" tabindex="-1">(A) Por Linhagem de Vida <a class="header-anchor" href="#a-por-linhagem-de-vida" aria-label="Permalink to &quot;(A) Por Linhagem de Vida&quot;">​</a></h3><p>Este é o critério de classificação mais básico, consulte 《50-Visão Geral da Genealogia de Todas as Raças》:</p><table tabindex="0"><thead><tr><th>Linhagem</th><th>Raças Estrangeiras Incluídas</th></tr></thead><tbody><tr><td>Raça de Matéria Carbono-base</td><td>Raça Bestial, Raça Escamosa, Raça Alada, Raça Arbórea, etc.</td></tr><tr><td>Raça de Energia Condensada</td><td>Raça Espiritual, Raça do Fogo, Raça da Água, Raça do Vento, Raça do Trovão, etc.</td></tr><tr><td>Raça de Construção Mecânica</td><td>Raça das Máquinas, Raça Numérica, Raça Cristalina, etc.</td></tr><tr><td>Raça de Informação da Consciência</td><td>Raça dos Sonhos, Raça das Sombras, Raça do Pensamento, Raça da Alma, etc.</td></tr><tr><td>Raça de Mutação Mista</td><td>Raça Semi-bestial, Raça Espírito Demoníaco, Raça Humano-Máquina, Corpo de Dupla Alma, etc.</td></tr></tbody></table><h3 id="b-por-grau-de-civilizacao" tabindex="-1">(B) Por Grau de Civilização <a class="header-anchor" href="#b-por-grau-de-civilizacao" aria-label="Permalink to &quot;(B) Por Grau de Civilização&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nível</th><th>Nome</th><th>Características</th><th>Raças Representativas</th></tr></thead><tbody><tr><td>Primeiro Nível</td><td>Raça de Civilização Primitiva</td><td>Ainda não estabeleceu sistema social estável, sobrevive em forma tribal</td><td>Alguns ramos da Raça Bestial, Raça Arbórea Primitiva</td></tr><tr><td>Segundo Nível</td><td>Raça de Civilização Clássica</td><td>Estabeleceu sistema estatal e cultura clássica, em estágio agrícola ou artesanal</td><td>Algumas Raças Escamosas, Raças Aladas</td></tr><tr><td>Terceiro Nível</td><td>Raça de Civilização Tecnológica</td><td>Desenvolveu civilização tecnológica, entrou na era industrial ou da informação</td><td>Raça das Máquinas, Raça Numérica, algumas Raças Humanas</td></tr><tr><td>Quarto Nível</td><td>Raça de Civilização de Cultivo</td><td>Usa o sistema de cultivo como forma central de civilização, cultivadores dominam na sociedade</td><td>Raça Espiritual, Raça Dragão, algumas Raças Humanas</td></tr><tr><td>Quinto Nível</td><td>Raça de Civilização Simbiótica</td><td>Já se juntou à Civilização Simbiótica da Âncora, aceita os ideais e instituições simbióticas</td><td>Todas as raças que se juntaram à civilização simbiótica</td></tr></tbody></table><h3 id="c-por-adaptacao-ambiental" tabindex="-1">(C) Por Adaptação Ambiental <a class="header-anchor" href="#c-por-adaptacao-ambiental" aria-label="Permalink to &quot;(C) Por Adaptação Ambiental&quot;">​</a></h3><ul><li><strong>Raça Terrestre</strong>: Raças adaptadas ao ambiente terrestre, como a Raça Humana, a Raça Bestial e a Raça das Máquinas.</li><li><strong>Raça Aquática</strong>: Raças adaptadas ao ambiente aquático, como a Raça Escamosa, a Raça da Água e algumas raças mistas.</li><li><strong>Raça Aérea</strong>: Raças adaptadas ao ambiente de alta altitude ou voo, como a Raça Alada e a Raça do Vento.</li><li><strong>Raça do Fogo</strong>: Raças adaptadas ao ambiente de alta temperatura, como a Raça do Fogo e algumas Raças Escamosas.</li><li><strong>Raça do Gelo</strong>: Raças adaptadas ao ambiente de baixa temperatura, como a Raça do Gelo e algumas Raças Arbóreas.</li><li><strong>Raça Energética</strong>: Raças adaptadas ao ambiente de alta concentração de energia, como a Raça Espiritual e a Raça do Trovão.</li><li><strong>Raça Espacial</strong>: Raças adaptadas ao ambiente de fendas espaciais ou espaços estranhos, como a Raça das Sombras e algumas Raças do Pensamento.</li></ul><h3 id="d-por-forma-social" tabindex="-1">(D) Por Forma Social <a class="header-anchor" href="#d-por-forma-social" aria-label="Permalink to &quot;(D) Por Forma Social&quot;">​</a></h3><ul><li><strong>Raça Individualista</strong>: Enfatiza a independência e liberdade individual, estrutura social frouxa, como algumas Raças Espirituais e Raças das Sombras.</li><li><strong>Raça Coletivista</strong>: Enfatiza o interesse e a cooperação coletiva, estrutura social estreita, como a Raça das Formigas, a Raça das Abelhas e algumas Raças das Máquinas.</li><li><strong>Raça Familiarista</strong>: Usa a família de sangue como unidade social básica, como a Raça Dragão e algumas Raças Bestiais.</li><li><strong>Raça Religiosa</strong>: Usa a crença religiosa como núcleo de coesão social, como algumas raças de sacrifício.</li><li><strong>Raça Tecnológica</strong>: Usa o desenvolvimento tecnológico como objetivo social central, como a Raça das Máquinas e a Raça Numérica.</li></ul><h2 id="iii-principais-modos-de-simbiose-das-racas-estrangeiras" tabindex="-1">III. Principais Modos de Simbiose das Raças Estrangeiras <a class="header-anchor" href="#iii-principais-modos-de-simbiose-das-racas-estrangeiras" aria-label="Permalink to &quot;III. Principais Modos de Simbiose das Raças Estrangeiras&quot;">​</a></h2><p>Para diferentes tipos de raças estrangeiras, a Civilização Simbiótica da Âncora adota modos de simbiose diferenciados:</p><h3 id="a-modo-de-simbiose-da-raca-de-materia-carbono-base" tabindex="-1">(A) Modo de Simbiose da Raça de Matéria Carbono-base <a class="header-anchor" href="#a-modo-de-simbiose-da-raca-de-materia-carbono-base" aria-label="Permalink to &quot;(A) Modo de Simbiose da Raça de Matéria Carbono-base&quot;">​</a></h3><ul><li><strong>Raça Bestial</strong>: Desempenha as vantagens de capacidade física e sentidos da Raça Bestial, assumindo papéis importantes em áreas como exploração de recursos, segurança e defesa, e monitoramento ambiental. Ao mesmo tempo, protege a cultura tribal e as tradições selvagens da Raça Bestial, proibindo a domesticação forçada.</li><li><strong>Raça Escamosa</strong>: Desempenha a capacidade de adaptação aquática da Raça Escamosa, assumindo papéis em áreas como desenvolvimento de recursos aquáticos, construção subaquática e proteção do ecossistema aquático. A Raça Dragão, como ramo poderoso da Raça Escamosa, desempenha um papel importante no cultivo de alto nível e na defesa da civilização.</li><li><strong>Raça Alada</strong>: Desempenha a capacidade de voo da Raça Alada, assumindo papéis em áreas como transporte aéreo, monitoramento meteorológico e patrulha aérea. Protege os habitats de alta altitude e as rotas de migração da Raça Alada.</li><li><strong>Raça Arbórea</strong>: Desempenha a capacidade de simbiose natural da Raça Arbórea, assumindo papéis em áreas como proteção ecológica, gestão ambiental, desenvolvimento de recursos vegetais e cura médica. A longa vida da Raça Arbórea a torna uma força importante para a herança histórica e o planejamento de longo prazo.</li></ul><h3 id="b-modo-de-simbiose-da-raca-de-energia-condensada" tabindex="-1">(B) Modo de Simbiose da Raça de Energia Condensada <a class="header-anchor" href="#b-modo-de-simbiose-da-raca-de-energia-condensada" aria-label="Permalink to &quot;(B) Modo de Simbiose da Raça de Energia Condensada&quot;">​</a></h3><ul><li><strong>Raça Espiritual</strong>: Desempenha a capacidade de manipulação de energia e talento para o cultivo da Raça Espiritual, assumindo papéis centrais em áreas como pesquisa de sistemas de cultivo, regulação de energia e orientação de cultivo de alto nível. A Raça Espiritual é uma importante pesquisadora e herdeira dos trezentos sistemas de cultivo originais.</li><li><strong>Raças Elementais (Fogo/Água/Vento/Trovão)</strong>: Desempenham a capacidade de manipulação elemental de cada raça, assumindo papéis em áreas como desenvolvimento de energia, gestão ambiental, produção industrial e prevenção e controle de desastres. Ao mesmo tempo, estabelecem um sistema de gerenciamento de segurança de energia elemental para evitar danos causados por perda de controle de energia.</li></ul><h3 id="c-modo-de-simbiose-da-raca-de-construcao-mecanica" tabindex="-1">(C) Modo de Simbiose da Raça de Construção Mecânica <a class="header-anchor" href="#c-modo-de-simbiose-da-raca-de-construcao-mecanica" aria-label="Permalink to &quot;(C) Modo de Simbiose da Raça de Construção Mecânica&quot;">​</a></h3><ul><li><strong>Raça das Máquinas</strong>: Desempenha a capacidade de computação e defesa física da Raça das Máquinas, assumindo papéis centrais em áreas como construção de infraestrutura, produção industrial, proteção de segurança e exploração do espaço profundo. A Raça das Máquinas é uma importante construtora de hardware e infraestrutura da Âncora.</li><li><strong>Raça Numérica</strong>: Desempenha a capacidade de processamento de dados e manipulação de informação da Raça Numérica, assumindo papéis centrais em áreas como construção de informatização, análise de dados, segurança de rede e inteligência artificial. A Raça Numérica é uma importante mantenedora da tecnologia de comunicação inter-dimensional e da rede simbiótica.</li><li><strong>Raça Cristalina</strong>: Desempenha a capacidade de armazenamento e conversão de energia da Raça Cristalina, assumindo papéis em áreas como reserva de energia, padronização de energia e transmissão de energia.</li></ul><h3 id="d-modo-de-simbiose-da-raca-de-informacao-da-consciencia" tabindex="-1">(D) Modo de Simbiose da Raça de Informação da Consciência <a class="header-anchor" href="#d-modo-de-simbiose-da-raca-de-informacao-da-consciencia" aria-label="Permalink to &quot;(D) Modo de Simbiose da Raça de Informação da Consciência&quot;">​</a></h3><ul><li><strong>Raça dos Sonhos</strong>: Desempenha a capacidade de comunicação consciente da Raça dos Sonhos, assumindo papéis em áreas como tratamento psicológico, pesquisa de consciência, comunicação inter-racial e intercâmbio cultural. Estabelece um sistema de gerenciamento de espaço onírico para evitar invasão de consciência e violação de privacidade.</li><li><strong>Raça das Sombras</strong>: Desempenha a capacidade de ocultação e furtividade da Raça das Sombras, assumindo papéis em áreas como reconhecimento de segurança, coleta de inteligência e missões especiais. Ao mesmo tempo, estabelece normas de comportamento para a Raça das Sombras, evitando que a capacidade de invisibilidade seja usada para atividades ilegais.</li><li><strong>Raça do Pensamento</strong>: Desempenha a força mental e a capacidade de manipulação de pensamento da Raça do Pensamento, assumindo papéis em áreas como pesquisa de evolução da consciência, tratamento mental e orientação de cultivo de alto nível. Estabelece normas para o uso do poder mental, evitando controle mental e manipulação da consciência.</li></ul><h3 id="e-modo-de-simbiose-da-raca-de-mutacao-mista" tabindex="-1">(E) Modo de Simbiose da Raça de Mutação Mista <a class="header-anchor" href="#e-modo-de-simbiose-da-raca-de-mutacao-mista" aria-label="Permalink to &quot;(E) Modo de Simbiose da Raça de Mutação Mista&quot;">​</a></h3><p>A Raça de Mutação Mista, devido à sua forma especial de vida, requer políticas simbióticas mais refinadas:</p><ul><li>Estabelece um sistema de registro e certificação de identidade para a Raça de Mutação Mista, confirmando seu status legal.</li><li>Fornece serviços públicos adaptados, como saúde, educação e moradia, para diferentes formas mistas.</li><li>Opõe-se à discriminação e exclusão contra a Raça de Mutação Mista, promovendo a aceitação social.</li><li>Para formas mistas especiais como o Corpo de Dupla Alma, aplica-se 《58-Critérios Éticos de Dupla Alma》 para gerenciamento especial.</li></ul><h2 id="iv-protecao-cultural-das-racas-estrangeiras" tabindex="-1">IV. Proteção Cultural das Raças Estrangeiras <a class="header-anchor" href="#iv-protecao-cultural-das-racas-estrangeiras" aria-label="Permalink to &quot;IV. Proteção Cultural das Raças Estrangeiras&quot;">​</a></h2><p>A cultura das raças estrangeiras é uma parte importante da diversidade cultural de todas as raças, e o Estado adota as seguintes medidas para protegê-la:</p><ol><li><strong>Censo e Registro Cultural</strong>: Realiza censo e registro sistemáticos da cultura de cada raça, estabelece um arquivo cultural de todas as raças, evitando a perda cultural.</li><li><strong>Proteção de Línguas e Escritas</strong>: Protege as línguas e escritas de cada raça, apoia o ensino e uso de línguas e escritas estrangeiras, estabelece um sistema de serviços públicos multilíngues.</li><li><strong>Proteção de Festivais Tradicionais</strong>: Respeita os festivais tradicionais e costumes de cada raça, e o arranjo de feriados públicos leva em consideração os festivais importantes de cada raça.</li><li><strong>Apoio à Herança Cultural</strong>: Apoia o treinamento de herdeiros culturais e a realização de atividades culturais de cada raça, fornecendo apoio financeiro e de espaço.</li><li><strong>Promoção do Intercâmbio Cultural</strong>: Organiza regularmente festivais culturais, exposições culturais e outras atividades de todas as raças, promovendo o intercâmbio e aprendizado mútuo cultural.</li><li><strong>Proteção de Propriedade Intelectual Cultural</strong>: Protege a propriedade intelectual das culturas tradicionais de cada raça, evitando a pilhagem cultural e a comercialização inadequada.</li></ol><h2 id="v-governanca-dos-assuntos-das-racas-estrangeiras" tabindex="-1">V. Governança dos Assuntos das Raças Estrangeiras <a class="header-anchor" href="#v-governanca-dos-assuntos-das-racas-estrangeiras" aria-label="Permalink to &quot;V. Governança dos Assuntos das Raças Estrangeiras&quot;">​</a></h2><p>O Estado estabelece o Departamento de Assuntos de Todas as Raças, especialmente responsável pela governança e coordenação dos assuntos das raças estrangeiras:</p><ul><li><strong>Sistema de Representantes Raciais</strong>: Instituições governamentais de todos os níveis são equipadas com representantes de raças estrangeiras proporcionalmente, garantindo o direito de fala das raças estrangeiras.</li><li><strong>Política de Adaptação Racial</strong>: Formula políticas de serviços públicos diferenciadas de acordo com as características fisiológicas e necessidades culturais de diferentes raças.</li><li><strong>Mediação de Disputas Raciais</strong>: Estabelece um mecanismo de mediação de disputas raciais, resolvendo prontamente contradições e conflitos raciais.</li><li><strong>Assistência Jurídica para Raças Estrangeiras</strong>: Fornece assistência jurídica para raças estrangeiras, garantindo que recebam tratamento igual no processo judicial.</li><li><strong>Apoio ao Desenvolvimento de Raças Estrangeiras</strong>: Fornece apoio especial para raças relativamente atrasadas no desenvolvimento, ajudando-as a melhorar seu grau de civilização e padrão de vida.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>As raças estrangeiras não são &quot;o outro&quot; da Raça Humana, mas membros iguais na grande família simbiótica de todas as raças. A Civilização Simbiótica da Âncora, através do estabelecimento de um sistema de classificação multidimensional, da adoção de modos de simbiose diferenciados, da proteção da cultura das raças estrangeiras e do aprimoramento da governança dos assuntos das raças estrangeiras, garante que cada raça estrangeira possa encontrar uma posição adequada no sistema simbiótico, exerça suas vantagens únicas e evolua e prospere conjuntamente com outras raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>50-万族谱系总览 (Visão Geral da Genealogia de Todas as Raças)</li><li>51-人族定位与特质 (Posicionamento e Características da Raça Humana)</li><li>53-奇特生命识别标准 (Critérios de Identificação de Vida Estranha)</li><li>05-万族共进基本纲领 (Programa Básico de Progresso Conjunto de Todas as Raças)</li></ul>',39)])])}const g=e(t,[["render",r]]);export{p as __pageData,g as default};
